verification_commands.ac2:
root=$(git rev-parse --show-toplevel 2>/dev/null) || root=.
cd "$root" || { echo "FAIL AC-2: cannot cd to the repo root"; exit 1; }
[ -f frontend/package.json ] || { echo "FAIL AC-2: not run from the TableQueue repo root (frontend/package.json missing)"; exit 1; }
[ -d frontend/node_modules ] || { echo "FAIL AC-2: not measured - frontend/node_modules is missing (cd frontend && npm install)"; exit 1; }
[ -f frontend/eslint.config.js ] || { echo "FAIL AC-2: frontend/eslint.config.js does not exist - no ruleset ships"; exit 1; }
mkdir -p frontend/.scratch
out="frontend/.scratch/_t22ac2.out"
rm -f "$out"
node -e '
const p = require("./frontend/package.json");
const d = p.devDependencies || {};
const problems = [];
if (!d["eslint-plugin-react-hooks"]) problems.push("eslint-plugin-react-hooks missing from devDependencies");
if (!d["typescript-eslint"] && !d["@typescript-eslint/eslint-plugin"]) problems.push("no typescript-eslint toolchain in devDependencies (want the typescript-eslint meta-package or @typescript-eslint/eslint-plugin)");
if (d["@typescript-eslint/eslint-plugin"] && !d["@typescript-eslint/parser"]) problems.push("@typescript-eslint/parser missing from devDependencies");
if (problems.length) { for (const x of problems) console.log("  " + x); process.exit(1); }
console.log("devDeps ok: eslint-plugin-react-hooks@%s typescript-eslint=%s", d["eslint-plugin-react-hooks"], d["typescript-eslint"] || d["@typescript-eslint/eslint-plugin"]);
' > "$out" 2>&1
rc=$?
if [ $rc -ne 0 ]; then
  cat "$out"
  echo "FAIL AC-2: the ruleset dependencies do not ship in frontend/package.json - detail above"
  rm -f "$out"; rmdir frontend/.scratch 2>/dev/null
  exit 1
fi
( cd frontend && npx eslint --print-config src/main.tsx > "../.scratch/_t22ac2_config.json" 2>&1 )
rc2=$?
if [ $rc2 -ne 0 ]; then
  cat frontend/.scratch/_t22ac2_config.json
  echo "FAIL AC-2: eslint --print-config src/main.tsx exited $rc2 - the config does not resolve for a real src file"
  rm -f "$out" frontend/.scratch/_t22ac2_config.json; rmdir frontend/.scratch 2>/dev/null
  exit 1
fi
node -e '
const fs = require("fs");
const cfg = JSON.parse(fs.readFileSync("frontend/.scratch/_t22ac2_config.json", "utf-8"));
const rules = cfg.rules || {};
const problems = [];
for (const name of ["react-hooks/rules-of-hooks", "react-hooks/exhaustive-deps", "@typescript-eslint/no-explicit-any"]) {
  const v = rules[name];
  const on = v === "error" || v === "warn" || v === 1 || v === 2 || (Array.isArray(v) && (v[0] === "error" || v[0] === "warn"));
  if (!on) problems.push(name + " is not enabled in the resolved config (value: " + JSON.stringify(v) + ")");
}
if (problems.length) { for (const x of problems) console.log("  " + x); process.exit(1); }
console.log("resolved config for src/main.tsx carries react-hooks rules-of-hooks/exhaustive-deps + @typescript-eslint/no-explicit-any");
' >> "$out" 2>&1
rc3=$?
if [ $rc3 -ne 0 ]; then
  cat "$out"
  echo "FAIL AC-2: the resolved config for a real src file does not carry the react-hooks + typescript-eslint recommended rules - detail above"
  rm -f "$out" frontend/.scratch/_t22ac2_config.json; rmdir frontend/.scratch 2>/dev/null
  exit 1
fi
rm -f "$out" frontend/.scratch/_t22ac2_config.json; rmdir frontend/.scratch 2>/dev/null
echo "PASS AC-2: ruleset ships and is in effect - react-hooks + typescript-eslint recommended rules are enabled in the resolved config for frontend/src/main.tsx"
exit 0

verification_commands.ac6:
root=$(git rev-parse --show-toplevel 2>/dev/null) || root=.
cd "$root" || { echo "FAIL AC-6: cannot cd to the repo root"; exit 1; }
[ -f frontend/package.json ] || { echo "FAIL AC-6: not run from the TableQueue repo root (frontend/package.json missing)"; exit 1; }
[ -d frontend/node_modules ] || { echo "FAIL AC-6: not measured - frontend/node_modules is missing (cd frontend && npm install)"; exit 1; }
mkdir -p frontend/.scratch
out="frontend/.scratch/_t22ac6.out"
rm -f "$out"
node -e '
const p = require("./frontend/package.json");
const d = p.devDependencies || {};
const problems = [];
const ev = d["eslint"] || "";
if (!/^(\^|~)?9\./.test(ev)) problems.push("eslint devDependency is " + JSON.stringify(ev) + ", want 9.x (the audit item is the eslint 9 flat config - a downgrade is not a fix)");
if ((p.scripts || {}).lint !== "eslint .") problems.push("the lint script is " + JSON.stringify((p.scripts || {}).lint) + ", want the shipped \"eslint .\"");
if (problems.length) { for (const x of problems) console.log("  " + x); process.exit(1); }
console.log("eslint pinned at %s, lint script is the shipped \"eslint .\"", ev);
' > "$out" 2>&1
rc=$?
legacy=0
for f in frontend/.eslintrc.js frontend/.eslintrc.cjs frontend/.eslintrc.json frontend/.eslintrc.yml frontend/.eslintrc.yaml frontend/.eslintrc frontend/eslint.config.mjs frontend/eslint.config.cjs; do
  [ -e "$f" ] && legacy=$((legacy + 1))
done
if [ $rc -ne 0 ] || [ "$legacy" -ne 0 ] || [ ! -f frontend/eslint.config.js ]; then
  cat "$out"
  echo "FAIL AC-6: the fix drifted off the eslint 9 flat config (dep/script check rc=$rc, legacy_or_alt_config_files=$legacy want 0, and frontend/eslint.config.js must exist)"
  rm -f "$out"; rmdir frontend/.scratch 2>/dev/null
  exit 1
fi
rm -f "$out"; rmdir frontend/.scratch 2>/dev/null
echo "PASS AC-6: the fix stays on eslint 9 (9.x devDep, shipped \"eslint .\" script, zero legacy .eslintrc.* files, flat config at frontend/eslint.config.js)"
exit 0
